solution:
R, C = map(int, input().split())
grid = [input() for _ in range(R)]

for r in range(R):
    line = ""
    for c in range(C):
        if grid[r][c] == "*":
            line += "*"
            continue
        count = 0
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == "*":
                    count += 1
        line += str(count)
    print(line)
